head.b:skin:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #090d16;
  font-family: 'Cairo', 'Tajawal', sans-serif;
}
#app-frame {
  width: 100%;
  height: 100%;
  height: 100vh;
  border: none;
  display: block;
}
.blogger-credit {
  display: none;
}
